// Independent exhaustive c0 coverage checker: path walking, not producer DSU.
#include <bits/stdc++.h>
using namespace std;using E=vector<pair<int,int>>;using Sig=array<uint64_t,2>;
struct Family{int u,v;vector<E>a,b;};vector<Family> fam;vector<E> two;vector<pair<Sig,vector<E>>> bclass;map<Sig,vector<E>> bySig;unordered_set<string> residual;E current;long long na=0,nb=0,rem=0,missing=0;
E readE(ifstream&in){int n;in>>n;E e(n);for(auto&[a,b]:e)in>>a>>b;return e;}
int paths(const E&f,const E&n,int u,int v,bool B,bool twoport=false){int adj[16][2],deg[16]={};auto add=[&](int x,int y){if(deg[x]>=2||deg[y]>=2)return false;for(int j=0;j<deg[x];j++)if(adj[x][j]==y)return false;adj[x][deg[x]++]=y;adj[y][deg[y]++]=x;return true;};for(auto[x,y]:f)if(!add(x,y))return -1;for(auto[x,y]:n)if(!add(x,y))return -1;int ends[4]={3,15,u,v};int ne=twoport?2:4;unsigned seen=0;int firstend=-1;for(int x=0;x<16;x++){if(B&&(x==1||x==2)){if(deg[x])return -1;continue;}bool ep=false;for(int j=0;j<ne;j++)if(ends[j]==x)ep=true;if(deg[x]!=(ep?1:2))return -1;}for(int j=0;j<ne;j++){int start=ends[j];if(seen>>start&1u)continue;int prev=-1,x=start;while(true){if(seen>>x&1u)return -1;seen|=1u<<x;int next=-1;for(int k=0;k<deg[x];k++)if(adj[x][k]!=prev){if(next>=0)return -1;next=adj[x][k];}if(next<0){if(start==3)firstend=x;break;}prev=x;x=next;}}if(seen!=(B?(65535u&~6u):65535u))return -1;if(twoport)return firstend==15?0:-1;for(int j=1;j<4;j++)if(firstend==ends[j])return j-1;return -1;}
Sig signature(const E&f,bool B){Sig s{};if(!B)s[1]|=1ull<<44;else for(auto&n:two)if(paths(f,n,0,0,true,true)>=0){s[1]|=1ull<<44;break;}for(int k=0;k<(int)fam.size();k++){auto&p=fam[k];if(p.b.empty())continue;for(auto&n:B?p.b:p.a){int z=paths(f,n,p.u,p.v,B);if(z<0)continue;for(int j=0;j<3;j++)if(!B||j!=z){int b=3*k+(B?j:z);s[b/64]|=1ull<<(b%64);if(!B)break;}}}return s;}
int lift(int x,bool B){return (x&3)|((x&12)<<1)|(B?0:4);}
void assess(bool B){if(B){nb++;bySig[signature(current,true)].push_back(current);return;}na++;Sig a=signature(current,false);for(auto&[b,ls]:bclass)if(!((a[0]&b[0])|(a[1]&b[1])))for(auto&f:ls){string r;for(auto[x,y]:current){r.push_back(char(lift(x,false)));r.push_back(char(lift(y,false)));}for(auto[x,y]:f){r.push_back(char(lift(x,true)));r.push_back(char(lift(y,true)));}rem++;if(!residual.count(r))missing++;}}
void gen(unsigned mask,bool B){if(!mask){assess(B);return;}int x=__builtin_ctz(mask);mask^=1u<<x;for(int y=x+1;y<16;y++)if(mask>>y&1u){current.push_back({x,y});gen(mask^(1u<<y),B);current.pop_back();}}
int main(){ifstream in("research/six_directions/t15_core4_c0_patterns.txt");int nf;in>>nf;for(int i=0;i<nf;i++){Family f;int na,nb;in>>f.u>>f.v>>na>>nb;for(int j=0;j<na;j++)f.a.push_back(readE(in));for(int j=0;j<nb;j++)f.b.push_back(readE(in));fam.push_back(f);}int nt;in>>nt;for(int j=0;j<nt;j++)two.push_back(readE(in));ifstream rin("research/six_directions/t15_core4_fourbridge_c0_residual_inputs.bin",ios::binary);char raw[26];while(rin.read(raw,26))if(!residual.insert(string(raw,26)).second)return 3;gen(65535u&~((1u<<0)|(1u<<1)|(1u<<2)|(1u<<7)),true);for(auto&z:bySig)bclass.push_back(z);gen(65535u&~((1u<<3)|(1u<<15)),false);cout<<"{\"A_count\":"<<na<<",\"B_count\":"<<nb<<",\"B_signatures\":"<<bclass.size()<<",\"required_residual\":"<<rem<<",\"saved_residual\":"<<residual.size()<<",\"missing\":"<<missing<<"}\n";return missing||rem!=residual.size();}
